"""Output code that every generator shares, so that generated files share one form."""

import os
import re

import tools
from tools.lint import includes
from tools.lint import rewrap

ROOT = tools.ROOT

WEBREF = os.path.join(ROOT, "third_party", "webref")

# The longest line that lint accepts.
LINE_LIMIT = rewrap.lint.LINE_LIMIT

WEBREF_SOURCE = "the W3C webref editor's draft extracts"


def webref_url(directory):
    """Returns the URL of the tree of editor's draft extracts under `directory`."""
    return "https://github.com/w3c/webref/tree/main/ed/" + directory


def banner(generator, *source):
    """Returns the comment lines that open a generated file. The first line names the generator and the inputs that it
    read, and each later line is the URL of an input."""
    named = [s for s in source if not s.startswith("https://")]
    urls = [s for s in source if s.startswith("https://")]
    text = "Generated by %s%s. Do not edit." % (os.path.basename(generator),
                                                 " from " + " and ".join(named) if named else "")
    return "// %s\n" % text + "".join("// %s\n" % url for url in urls)


def namespaced(head, body, public=False):
    """Returns a generated file that has `head` followed by `body`, with `body` in pr_impl inside an assume-nonnull
    region. With `public`, what follows the anonymous namespace in `body` defines the C API, after pr_impl."""
    if public:
        split = body.index("\n} // namespace\n") + 1
        return (head + ["\nPR_ASSUME_NONNULL_BEGIN\n\nnamespace pr_impl {\n"] + body[:split]
                + ["\n} // namespace pr_impl\n\nusing namespace pr_impl;\n"] + body[split:]
                + ["\nPR_ASSUME_NONNULL_END\n"])
    return (head + ["\nPR_ASSUME_NONNULL_BEGIN\n\nnamespace pr_impl {\n"] + body
            + ["\n} // namespace pr_impl\n\nPR_ASSUME_NONNULL_END\n"])


# Core's view types, each with the header that defines it and the names that need it.
VIEW_HEADERS = (("pr/string_view.h", re.compile(r"\bPrStringView\b|\bPR_SV\(")),
                ("pr/byte_view.h", re.compile(r"\bPrByteView\b")))


def with_view_includes(text):
    """Returns the header `text` with an include of each view type's header that its code names and it lacks. The
    include goes after the first, and the caller orders them."""
    code = re.sub(r"//[^\n]*|/\*.*?\*/", "", text, flags=re.S)
    needed = ['#include "%s"\n' % header for header, uses in VIEW_HEADERS
              if uses.search(code) and '"%s"' % header not in text]
    first = re.search(r'^#include "[^"]+"\n', text, re.M)
    if not needed or first is None:
        return text
    return text[:first.end()] + "".join(needed) + text[first.end():]


def write(path, chunks):
    """Writes the file, with its comment paragraphs refilled to the line limit that lint requires. A header includes the
    headers of the view types that it names."""
    text = "".join(chunks)
    if path.endswith(".h"):
        text = with_view_includes(text)
    if path.endswith((".h", ".cpp")):
        text = includes.ordered_text(path, rewrap.rewrap(text))
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    print("wrote %s (%d bytes)" % (path, len(text.encode("utf-8"))))


def c_string(text):
    """Returns a C string literal of `text` encoded as UTF-8. A byte outside printable ASCII becomes an octal escape."""
    out = []
    for byte in text.encode("utf-8"):
        if byte == 0x22 or byte == 0x5C:
            out.append("\\" + chr(byte))
        elif 0x20 <= byte < 0x7F:
            out.append(chr(byte))
        else:
            out.append("\\%03o" % byte)
    return '"%s"' % "".join(out)


def table(declaration, values, per_line=1, comments=None):
    """Returns an array definition. `declaration` is everything to the left of the `=`, and each value is a C
    expression. With `comments`, each value goes on its own line with its comment beside it."""
    out = ["\n%s = {\n" % declaration]
    if comments is not None:
        width = max(len(str(value)) for value in values) + 1
        out += ["    %s  // %s\n" % ((str(value) + ",").ljust(width), comment) for value,
                comment in zip(values, comments)]
    else:
        for at in range(0, len(values), per_line):
            out.append("    " + ", ".join(str(v) for v in values[at:at + per_line]) + ",\n")
    out.append("};\n")
    return "".join(out)


def bitset(declaration, bits, names=None):
    """Returns a bitset definition in the form that pr/bitset.h reads. `declaration` is everything to the left of
    the `=`, and bit i is bits[i], in 64-bit words. With `names`, each word follows a comment that names the bits it
    sets."""
    out = ["\n%s = {\n" % declaration]
    for at in range(0, len(bits), 64):
        word = bits[at:at + 64]
        if names is not None:
            line = "   "
            for name in [names[at + i] for i, bit in enumerate(word) if bit]:
                if len(line) + len(name) + 2 > 100:
                    out.append(line + "\n")
                    line = "   "
                line += " %s," % name if line != "   " else " // %s," % name
            if line != "   ":
                out.append(line.rstrip(",") + "\n")
        out.append("    UINT64_C(0x%016x),\n" % sum(1 << i for i, bit in enumerate(word) if bit))
    out.append("};\n")
    return "".join(out)


def enum_members(members, first=None, marker=None, note=()):
    """Returns the member lines of an enum from (ident, comment) pairs, with the comments aligned in a column. A comment
    that does not fit beside its member goes above it, between blank lines, so it must be written as sentences.

    `marker` is a member that marks the start of a range that runs to the last member. It goes before
    `members[first]`, under the lines of `note`, and `members[first]` takes its value.
    """
    members = [("%s = %s" % (ident, marker) if index == first else ident, comment)
               for index, (ident, comment) in enumerate(members)]
    width = max(len(ident) for ident, _ in members) + 1
    out = []
    for index, (ident, comment) in enumerate(members):
        if index == first:
            out.append("\n" + "".join("    // %s\n" % line for line in note))
            out.append("    %s,\n" % marker)
        line = "    %s  %s" % ((ident + ",").ljust(width), "// " + comment if comment else "")
        if len(line) > LINE_LIMIT:
            above = "    // %s\n    %s,\n\n" % (comment, ident)
            out.append(above if not out or out[-1].endswith("\n\n") else "\n" + above)
        else:
            out.append(line.rstrip() + "\n")
    if out and out[-1].endswith("\n\n"):
        out[-1] = out[-1][:-1]
    return out
